input.csh:
# cd $workDir/INPUT if ( -e coupler.res ) then set fmonth = `awk '/Current model/ { print $2 }' coupler.res | xargs printf '%2.2d'` else set fmonth = 01 endif
# select nudging files based on restart time set year_num = `awk '/Current model time:/ {printf("%4.4d", $1)}' coupler.res` set month_num = `awk '/Current model time:/ {printf("%2.2d", $2)}' coupler.res` set day_num = `awk '/Current model time:/ {printf("%2.2d", $3)}' coupler.res` echo 'month=' month_num 'day=' day_num ## define the end file = 1st day of next month @ month2_num = $month_num + 1 @ year2_num = $year_num set day2_num = '01' if ( $month2_num > 12 ) then @ year2_num = $year_num + 1 @ month2_num = $month2_num - 12 endif if ( $month2_num < 10 ) then set month2_num = '0'$month2_num endif set NudgeStartdate = ${year_num}${month_num}${day_num} set NudgeEnddate = ${year2_num}${month2_num}${day2_num} set cfsr_ic_file = `echo /lustre/f2/dev/Xiaosong.Yang/archive/ada_data/CFSR/${year_num}/${NudgeStartdate}_00Z*nc` set cfsr_file_first = ${cfsr_ic_file} set cfsr_last_file = `echo /lustre/f2/dev/Xiaosong.Yang/archive/ada_data/CFSR/${year2_num}/${NudgeEnddate}_00Z*nc` set cfsr_file_last = ${cfsr_last_file}
cd $workDir
